('fae1bfab-9cd4-4923-984f-546917c482cf', 'Casela Nature Park Adventure', '<p>Experience the ultimate wildlife encounter at Casela Nature Parks. From African Safaris to walking with lions, this is the heart of adventure in Mauritius.</p>', 'Cascavelle', 'West', 4.8, 'https://images.unsplash.com/photo-1549480017-d76466a4b7e8?auto=format&fit=crop&q=80', '["Parking","Restaurant","Guide","Toilets","Gift Shop"]'::jsonb, 'land_activity', NULL, NULL, NULL, '2026-05-20T04:29:18.682799+00:00', '2026-05-20T04:29:18.682799+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, false, 0, NULL, false, 'Limited Time', true, false, 'Interaction with wildlife and African-inspired safari adventure.', NULL, NULL, 12, '[]'::jsonb, NULL, 0, NULL),
('fd6a1906-2de8-4c4e-a6ac-6dcd0ba4c312', 'Seven Coloured Earth & Chamarel', '<p>Visit the world-famous Seven Coloured Earth and the majestic Chamarel Waterfall. A must-see geological phenomenon in the lush South-West.</p>', 'Chamarel', 'South-West', 4.6, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80', '["Sightseeing","Geology","Nature"]'::jsonb, 'tour', NULL, NULL, NULL, '2026-05-20T04:29:19.665311+00:00', '2026-05-20T04:29:19.665311+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, false, 0, NULL, false, 'Limited Time', true, false, 'Natural wonder and scenic falls.', NULL, NULL, 12, '[]'::jsonb, NULL, 0, NULL),
('fed2a513-c944-40a7-a6f4-8ecf04df52df', 'Pamplemousses Botanical Garden', '<p>Stroll through one of the oldest botanical gardens in the Southern Hemisphere, famous for its giant Victoria amazonica water lilies.</p>', 'Pamplemousses', 'North', 4.5, 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&q=80', '["Gardening","History","Nature"]'::jsonb, 'activity', NULL, NULL, NULL, '2026-05-20T04:29:20.169283+00:00', '2026-05-20T04:29:20.169283+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, false, 0, NULL, false, 'Limited Time', true, false, 'Historic gardens and giant lilies.', NULL, NULL, 12, '[]'::jsonb, NULL, 0, NULL),
('ff1dc10a-2d84-48e5-a2d2-e72408be0608', 'Chamarel Ziplining', 'Fly over the mountains and waterfalls', 'Chamarel', 'South-West', 4.8, '/placeholders/activity_main.png', '["Safety Gear"]'::jsonb, 'activity', NULL, NULL, NULL, '2026-05-19T20:19:31.080568+00:00', '2026-05-19T20:19:31.080568+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, NULL, false, 0, NULL, false, 'Limited Time', true, false, NULL, NULL, NULL, 12, '[]'::jsonb, NULL, 0, NULL),
('ffccd842-fc1c-4d0d-9781-9a03bd87ab66', 'Coral Azur Beach Resort', '<p><span style="color: rgb(102, 102, 102); background-color: rgb(255, 255, 255);">At&nbsp;Coral&nbsp;Azur&nbsp;Beach&nbsp;Resort,&nbsp;we&nbsp;take&nbsp;your&nbsp;holidays&nbsp;seriously!&nbsp;For&nbsp;the&nbsp;last&nbsp;thirty&nbsp;years,&nbsp;our&nbsp;ethos&nbsp;is&nbsp;to&nbsp;make&nbsp;every&nbsp;holiday&nbsp;one&nbsp;to&nbsp;remember&nbsp;with&nbsp;our&nbsp;caring&nbsp;and&nbsp;personalized&nbsp;service,&nbsp;delivered&nbsp;by&nbsp;a&nbsp;team&nbsp;of&nbsp;passionate&nbsp;team&nbsp;members.&nbsp;Authentic&nbsp;warmth&nbsp;and&nbsp;generosity,&nbsp;this&nbsp;is&nbsp;what&nbsp;drives&nbsp;each&nbsp;member&nbsp;of&nbsp;the&nbsp;hotel&nbsp;each&nbsp;day!&nbsp;While&nbsp;complying&nbsp;to&nbsp;high-quality&nbsp;hospitality&nbsp;standards,&nbsp;they&nbsp;are&nbsp;on&nbsp;a&nbsp;mission:&nbsp;meet&nbsp;all&nbsp;your&nbsp;needs&nbsp;while&nbsp;making&nbsp;sure&nbsp;you&nbsp;experience&nbsp;the&nbsp;local&nbsp;Art&nbsp;of&nbsp;living!</span></p>', 'Mont Choisy', 'North Coast', 4.5, 'services/1778142053864-dmz0aso11r.jpg', '["Free Wifi","spa","land and water activities","kids club","Bar and Restaurant","Entertainment"]'::jsonb, 'hotel', NULL, NULL, NULL, '2026-05-07T08:27:50.053+00:00', '2026-05-11T12:45:22.951+00:00', '[]'::jsonb, '[]'::jsonb, NULL, 'active', NULL, NULL, '["services/1778142391661-kzd3vfbwi0q.webp","services/1778142402034-sboptk11pjh.jpg","services/1778142423685-a1jyazc2v9f.webp","services/1778142439699-7tocqwz81ks.jpg","services/1778142449010-705ytzwqus.jpg","services/1778142461837-ou0v6phmdqn.webp","services/1778503508026-6xljn96v32j.webp"]'::jsonb, '', '', NULL, '[]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, NULL, NULL, NULL, 'services/1778503465663-yrawwh7cu9k.jpg', false, 0, 'services/1778142025807-vrwjihzuz5.jpg', false, 'Limited Time', true, false, 'Coral Azur Beach Resort is a beachfront hotel in Mauritius with a pool, restaurant, and comfortable rooms. It is ideal for a relaxing holiday.', NULL, NULL, 12, '[{"id":"1778144855303","label":"Half Board"},{"id":"1778144861063","label":"Full Board"}]'::jsonb, NULL, 0, NULL);
